import{_ as p,a0 as n,w as a,s as d,I as e,x as i,a1 as t,A as o,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"DevOps 应聘者应该准备回答的 20 个问题 | LCTT x X-CMD","titleTemplate":false,"description":"DevOps 应聘者应该准备回答的 20 个问题 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"DevOps 应聘者应该准备回答的 20 个问题 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"DevOps 应聘者应该准备回答的 20 个问题 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20180308 20 questions DevOps job candidates should be prepared to answer","title":"DevOps 应聘者应该准备回答的 20 个问题","tag":"201811","desc":""},"relativePath":"201811/20180308 20 questions DevOps job candidates should be prepared to answer.md","filePath":"[post].md"}'),u={name:"201811/20180308 20 questions DevOps job candidates should be prepared to answer.md"};function m(f,l,g,T,b,v){const s=n("Link");return a(),d("div",null,[l[29]||(l[29]=e("h1",{id:"devops-应聘者应该准备回答的-20-个问题",tabindex:"-1"},[i("DevOps 应聘者应该准备回答的 20 个问题 "),e("a",{class:"header-anchor",href:"#devops-应聘者应该准备回答的-20-个问题","aria-label":"Permalink to “DevOps 应聘者应该准备回答的 20 个问题”"},"​")],-1)),l[30]||(l[30]=e("blockquote",null,[e("p",null,"想要建立一个积极，富有成效的工作环境？ 在招聘过程中要专注于寻找契合点。")],-1)),l[31]||(l[31]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/hire-job-career.png?itok=SrZo0QJ3",alt:""})],-1)),e("p",null,[l[1]||(l[1]=i("聘请一个不合适的人",-1)),t(s,{href:"https://www.shrm.org/resourcesandtools/hr-topics/employee-relations/pages/cost-of-bad-hires.aspx"},{default:o(()=>[...l[0]||(l[0]=[i("代价是很高的",-1)])]),_:1}),l[2]||(l[2]=i("。根据 Link 人力资源的首席执行官 Jörgen Sundberg 的统计，招聘、雇佣一名新员工将会花费公司$240,000 之多，当你进行了一次不合适的招聘：",-1))]),l[32]||(l[32]=r("<ul><li>你失去了他们的知识技能。</li><li>你失去了他们的人脉。</li><li>你的团队将可能进入到一个组织发展的震荡阶段</li><li>你的公司将会面临组织破裂的风险</li></ul><p>当你失去一名员工的时候，你就像丢失了公司版图中的一块。同样值得一提的是另一端的痛苦。应聘到一个错误工作岗位的员工会感受到很大的压力以及整个身心的不满意，甚至是健康问题。</p><p>另外一方面，当你招聘到合适的人时，新的员工将会：</p><ul><li>丰富公司现有的文化，使你的组织成为一个更好的工作场所。研究表明一个积极的工作文化能够帮助更长久推动财务业绩增长，而且如果你在一个欢快的环境中工作，你更有可能在生活中做的更好。</li><li>热爱和你的组织在一起工作。当人们热爱他们所在做的，他们会趋向于做的更好。</li></ul><p>招聘以适合或加强现有的文化在 DevOps 和敏捷团多中是必不可少的。也就是说雇佣到一个能够鼓励积极合作的人，以便来自不同背景，有着不同目标和工作方式的团队能够在一起有效的工作。你新雇佣的员工应该能够帮助团队合作来充分发挥放大他们的价值，同时也能够增加员工的满意度以及平衡组织目标的冲突。他或者她应该能够通过明智的选择工具和工作流来促进你的组织，文化就是一切。</p>",5)),e("p",null,[l[4]||(l[4]=i("作为我们 2017 年 11 月发布的一篇文章 ",-1)),t(s,{href:"https://opensource.com/article/17/11/inclusive-workforce-takes-work"},{default:o(()=>[...l[3]||(l[3]=[i("DevOps 的招聘经理应该准备回答的 20 个问题",-1)])]),_:1}),l[5]||(l[5]=i(" 的回应，这篇文章将会重点关注在如何招聘最适合的人。",-1))]),l[33]||(l[33]=r('<h3 id="为什么招聘走错了方向" tabindex="-1">为什么招聘走错了方向 <a class="header-anchor" href="#为什么招聘走错了方向" aria-label="Permalink to “为什么招聘走错了方向”">​</a></h3><p>很多公司现在用的典型的雇佣策略是基于人才过剩的基础上：</p><ul><li>在职位公告栏发布招聘。</li><li>关注具有所需才能的应聘者。</li><li>尽可能找多的候选者。</li><li>通过面试淘汰弱者。</li><li>通过正式的面试淘汰更多的弱者。</li><li>评估，投票，选择。</li><li>渐渐接近补偿。</li></ul><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/images/life-uploads/hiring_graphic.png?itok=1udGbkhB" alt=""></p><p>职位公告栏是有成千上万失业者人才过剩的经济大萧条时期发明的。在今天的求职市场上已经没有人才过剩了，然而我们仍然在使用基于此的招聘策略。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/images/life-uploads/732px-unemployed_men_queued_outside_a_depression_soup_kitchen_opened_in_chicago_by_al_capone_02-1931_-_nara_-_541927.jpg?itok=HSs4NjCN" alt=""></p><h3 id="雇佣最合适的人员-运用文化和情感" tabindex="-1">雇佣最合适的人员：运用文化和情感 <a class="header-anchor" href="#雇佣最合适的人员-运用文化和情感" aria-label="Permalink to “雇佣最合适的人员：运用文化和情感”">​</a></h3><p>在人才过剩雇佣策略背后的思想是设计工作岗位然后将人员安排进去。</p><p>反而应该反过来：寻找将会积极融入你的商业文化的人才，然后为他们寻找他们热爱的最合适的岗位。要想实现这样的目标，你必须能够围绕他们热情为他们创造工作岗位。</p>',9)),e("p",null,[l[8]||(l[8]=e("strong",null,"谁正在寻找一份工作？",-1)),l[9]||(l[9]=i(" 根据一份 2016 年对美国 50000 名开发者的调查显示，",-1)),t(s,{href:"https://insights.stackoverflow.com/survey/2016#work-job-discovery"},{default:o(()=>[...l[6]||(l[6]=[i("85.7% 的受访对象",-1)])]),_:1}),l[10]||(l[10]=i("要么对新的机会不感兴趣，要么对于寻找新工作没有积极性。在寻找工作的那部分中，有将近 ",-1)),t(s,{href:"https://insights.stackoverflow.com/survey/2016#work-job-discovery"},{default:o(()=>[...l[7]||(l[7]=[i("28.3% 的求职者",-1)])]),_:1}),l[11]||(l[11]=i("来自于朋友的推荐。如果你只是在那些在找工作的人中寻找人才，你将会错过高端的人才。",-1))]),e("p",null,[l[13]||(l[13]=e("strong",null,"运用团队力量去发现和寻找潜力的雇员",-1)),l[14]||(l[14]=i("。例如，戴安娜是你的团队中的一名开发者，她所能提供的机会是，她已经",-1)),t(s,{href:"https://research.hackerrank.com/developer-skills/2018/"},{default:o(()=>[...l[12]||(l[12]=[i("从事编程很多年",-1)])]),_:1}),l[15]||(l[15]=i("而且在期间已经结识了很多从事热爱他们所从事的工作的人。难道你不认为她所推荐的潜在员工在技能、知识和智慧上要比 HR 所寻找的要优秀吗？在要求戴安娜分享她同伴之前，通知她即将到来的使命任务，向她阐明你要雇佣潜在有探索精神的团队，描述在将来会需要的知识领域。",-1))]),l[34]||(l[34]=r('<p><strong>雇员想要什么？</strong>一份来自千禧年婴儿潮时期出生的人的对比综合性研究显示，20% 的人所想要的是相同的：</p><ol><li>对组织产生积极的影响</li><li>帮助解决社交或者环境上的挑战</li><li>和一群有动力的人一起工作</li></ol><h3 id="面试的挑战" tabindex="-1">面试的挑战 <a class="header-anchor" href="#面试的挑战" aria-label="Permalink to “面试的挑战”">​</a></h3><p>面试应该是招聘者和应聘者双方为了寻找最合适的人才进行的一次双方之间的对话。将面试聚焦在企业文化和情感对话两个问题上：这个应聘者将会丰富你的企业文化并且会热爱和你在一起工作吗？你能够在工作中帮他们取得成功吗？</p><p><strong>对于招聘经理来说：</strong> 每一次的面试都是你学习如何将自己的组织变得对未来的团队成员更有吸引力，并且每次积极的面试都可能是你发现人才（即使你不会雇佣）的机会。每个人都将会记得积极有效的面试的经历。即使他们不会被雇佣，他们将会和他们的朋友谈论这次经历，你会得到一个被推荐的机会。这有很大的好处：如果你无法吸引到这个人才，你也将会从中学习吸取经验并且改善。</p><p><strong>对面试者来说</strong>：每次的面试都是你释放激情的机会。</p><h3 id="助你释放潜在雇员激情的-20-个问题" tabindex="-1">助你释放潜在雇员激情的 20 个问题 <a class="header-anchor" href="#助你释放潜在雇员激情的-20-个问题" aria-label="Permalink to “助你释放潜在雇员激情的 20 个问题”">​</a></h3><ol><li>你热爱什么？</li><li>“今天早晨我已经迫不及待的要去工作”，你怎么看待这句话？</li><li>你曾经最快乐的是什么？</li><li>你曾经解决问题的最典型的例子是什么，你是如何解决的？</li><li>你如何看待配对学习？</li><li>你到达办公室和离开办公室心里最先想到的是什么？</li><li>你如果你有一次改变你之前或者现在的工作中的一件事的机会，将会是什么事？</li><li>当你在工作的时候，你最乐于去学习什么？</li><li>你的梦想是什么，你如何去实现？</li><li>你在学会如何去实现你的追求的时候想要或者需要什么？</li><li>你的价值观是什么？</li><li>你是如何坚守自己的价值观的？</li><li>在你的生活中平衡意味着什么？</li><li>你最引以为傲的工作交流能力是什么？为什么？</li><li>你最喜欢营造什么样的环境？</li><li>你喜欢别人怎样对待你？</li><li>你信任我们什么，如何验证？</li><li>告诉我们你在最近的一个项目中学习到什么？</li><li>我们还能知道你的其他方面的什么？</li><li>如果你正在雇佣我，你将会问我什么问题？</li></ol><hr>',9)),e("p",null,[l[17]||(l[17]=i("via: ",-1)),t(s,{href:"https://opensource.com/article/18/3/questions-devops-employees-should-answer"},{default:o(()=>[...l[16]||(l[16]=[i("https://opensource.com/article/18/3/questions-devops-employees-should-answer",-1)])]),_:1})]),e("p",null,[l[21]||(l[21]=i("作者：",-1)),t(s,{href:"https://opensource.com/users/catherinelouis"},{default:o(()=>[...l[18]||(l[18]=[i("Catherine Louis",-1)])]),_:1}),l[22]||(l[22]=i(" 译者：",-1)),t(s,{href:"https://github.com/FelixYFZ"},{default:o(()=>[...l[19]||(l[19]=[i("FelixYFZ",-1)])]),_:1}),l[23]||(l[23]=i(" 校对：",-1)),t(s,{href:"https://github.com/wxy"},{default:o(()=>[...l[20]||(l[20]=[i("wxy",-1)])]),_:1})]),e("p",null,[l[26]||(l[26]=i("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...l[24]||(l[24]=[i("LCTT",-1)])]),_:1}),l[27]||(l[27]=i(" 原创编译，",-1)),t(s,{href:"https://linux.cn/"},{default:o(()=>[...l[25]||(l[25]=[i("Linux中国",-1)])]),_:1}),l[28]||(l[28]=i(" 荣誉推出",-1))])])}const C=p(u,[["render",m]]);export{x as __pageData,C as default};
